import 'package:flutter_test/flutter_test.dart';
import 'package:auren/features/personal_ai_memory/domain/personal_ai_memory_policy.dart';
void main(){const p=PersonalAiMemoryPolicy();final now=DateTime.utc(2026,10,12);test('requires consent and rejects secrets',(){expect(p.evaluate(const MemoryProposal(key:'topic',sensitivity:MemorySensitivity.ordinary,consented:false),now).decision,MemoryDecision.requireConsent);expect(p.evaluate(const MemoryProposal(key:'secret',sensitivity:MemorySensitivity.secret,consented:true),now).decision,MemoryDecision.reject);});test('rejects noncanonical memory keys',(){expect(p.evaluate(const MemoryProposal(key:' topic ',sensitivity:MemorySensitivity.ordinary,consented:true),now).decision,MemoryDecision.reject);});test('rejects expired and forgotten memories',(){expect(p.evaluate(MemoryProposal(key:'x',sensitivity:MemorySensitivity.ordinary,consented:true,expiresAt:now),now).decision,MemoryDecision.reject);expect(p.evaluate(const MemoryProposal(key:'x',sensitivity:MemorySensitivity.ordinary,consented:true,forgetRequested:true),now).decision,MemoryDecision.reject);});}
